package com.cylldby.blocker.util

import android.content.Context
import android.util.Base64
import java.security.MessageDigest
import java.security.SecureRandom
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * Two deliberately asymmetric ways out of the night guard.
 *
 *  1. MASTER — 30 characters, generated by the app, shown exactly once. The
 *     owner copies it onto paper and leaves that paper in another room, so
 *     getting up and walking is the price of an impulse. It is SINGLE USE:
 *     the hash is destroyed the moment it is accepted, and a new note has to
 *     be written before it can ever be used again.
 *  2. EMERGENCY — 6 digits, typed in and kept by a relative or friend. The
 *     owner's UI never reveals it. It stays usable (the owner may genuinely
 *     need help), but every successful use increments a counter and records
 *     a timestamp, so the other person can see what happened.
 *
 * Only salted SHA-256 hashes are persisted; no plaintext is ever written to
 * disk. Neither password can be created or changed while the night window is
 * locked — otherwise the sleepy owner could simply invent a new one at 02:00.
 */
object UnlockManager {

    const val MASTER_LENGTH = 30
    const val EMERGENCY_LENGTH = 6
    const val MAX_ATTEMPTS = 5
    const val LOCKOUT_MINUTES = 10
    const val DEFAULT_UNLOCK_MINUTES = 30

    /** -1 means "until this night window ends". */
    val UNLOCK_OPTIONS = intArrayOf(15, 30, 60, -1)

    // No 0/O/1/I — a handwritten note must stay unambiguous.
    private const val ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"

    private const val PREFS = "night_unlock"
    private const val KEY_MASTER_SALT = "master_salt"
    private const val KEY_MASTER_HASH = "master_hash"
    private const val KEY_MASTER_SPENT = "master_spent"
    private const val KEY_EMERGENCY_SALT = "emergency_salt"
    private const val KEY_EMERGENCY_HASH = "emergency_hash"
    private const val KEY_EMERGENCY_COUNT = "emergency_count"
    private const val KEY_EMERGENCY_LAST = "emergency_last_ms"
    private const val KEY_FAIL_COUNT = "fail_count"
    private const val KEY_FAIL_UNTIL = "fail_until_ms"
    private const val KEY_UNLOCK_MINUTES = "unlock_minutes"

    enum class Result { MASTER, EMERGENCY, WRONG, THROTTLED, NO_KEYS, NOT_NIGHT }

    private fun prefs(c: Context) = c.getSharedPreferences(PREFS, Context.MODE_PRIVATE)

    // ----- Pure helpers (JVM-testable) -----

    /** Paper notes are often copied with spaces or dashes between groups. */
    fun normalizeMaster(raw: String): String =
        raw.uppercase(Locale.US).filter { it.isLetterOrDigit() }

    fun isEmergencyShape(raw: String): Boolean =
        raw.length == EMERGENCY_LENGTH && raw.all { it.isDigit() }

    fun generateMasterRaw(): String {
        val rnd = SecureRandom()
        return CharArray(MASTER_LENGTH) { ALPHABET[rnd.nextInt(ALPHABET.length)] }
            .concatToString()
    }

    /** Six groups of five, far easier to copy by hand than one long blob. */
    fun displayMaster(raw: String): String = raw.chunked(5).joinToString("-")

    private fun newSalt(): String {
        val bytes = ByteArray(16)
        SecureRandom().nextBytes(bytes)
        return Base64.encodeToString(bytes, Base64.DEFAULT)
    }

    private fun hash(raw: String, saltB64: String): String {
        val md = MessageDigest.getInstance("SHA-256")
        md.update(Base64.decode(saltB64, Base64.DEFAULT))
        return Base64.encodeToString(md.digest(raw.toByteArray(Charsets.UTF_8)), Base64.DEFAULT)
    }

    private fun matches(raw: String, saltB64: String?, stored: String?): Boolean {
        if (saltB64.isNullOrBlank() || stored.isNullOrBlank()) return false
        return try {
            MessageDigest.isEqual(hash(raw, saltB64).toByteArray(), stored.toByteArray())
        } catch (_: Exception) {
            false
        }
    }

    private fun canConfigure(c: Context) = !NightGuardManager.isSettingsLocked(c)

    // ----- Status (safe to show on the owner's screen) -----

    fun hasMaster(c: Context) = !prefs(c).getString(KEY_MASTER_HASH, "").isNullOrBlank()

    /** True after the one-shot paper password has been consumed. */
    fun isMasterSpent(c: Context) =
        !hasMaster(c) && prefs(c).getBoolean(KEY_MASTER_SPENT, false)

    fun hasEmergency(c: Context) =
        !prefs(c).getString(KEY_EMERGENCY_HASH, "").isNullOrBlank()

    fun emergencyUseCount(c: Context) = prefs(c).getInt(KEY_EMERGENCY_COUNT, 0)

    fun lastEmergencyUseText(c: Context): String {
        val t = prefs(c).getLong(KEY_EMERGENCY_LAST, 0L)
        if (t <= 0L) return ""
        return SimpleDateFormat("MM-dd HH:mm", Locale.getDefault()).format(Date(t))
    }

    fun unlockMinutes(c: Context) =
        prefs(c).getInt(KEY_UNLOCK_MINUTES, DEFAULT_UNLOCK_MINUTES)

    fun unlockLabel(c: Context): String = when (val m = unlockMinutes(c)) {
        -1 -> "到天亮"
        else -> "$m 分钟"
    }

    fun isThrottled(c: Context) =
        System.currentTimeMillis() < prefs(c).getLong(KEY_FAIL_UNTIL, 0L)

    fun throttleRemainingMinutes(c: Context) =
        ((prefs(c).getLong(KEY_FAIL_UNTIL, 0L) - System.currentTimeMillis()) / 60_000L + 1)
            .coerceAtLeast(0L)

    fun attemptsLeft(c: Context) =
        (MAX_ATTEMPTS - prefs(c).getInt(KEY_FAIL_COUNT, 0)).coerceAtLeast(0)

    // ----- Setup. All of these refuse to run at night. -----

    fun setMaster(c: Context, raw: String): Boolean {
        if (!canConfigure(c)) return false
        val normalized = normalizeMaster(raw)
        if (normalized.length != MASTER_LENGTH || normalized.any { it !in ALPHABET }) return false
        val salt = newSalt()
        prefs(c).edit()
            .putString(KEY_MASTER_SALT, salt)
            .putString(KEY_MASTER_HASH, hash(normalized, salt))
            .putBoolean(KEY_MASTER_SPENT, false)
            .apply()
        return true
    }

    fun setEmergency(c: Context, raw: String): Boolean {
        if (!canConfigure(c)) return false
        if (!isEmergencyShape(raw)) return false
        val salt = newSalt()
        prefs(c).edit()
            .putString(KEY_EMERGENCY_SALT, salt)
            .putString(KEY_EMERGENCY_HASH, hash(raw, salt))
            .apply()
        return true
    }

    fun cycleUnlockMinutes(c: Context): Boolean {
        if (!canConfigure(c)) return false
        val current = unlockMinutes(c)
        val at = UNLOCK_OPTIONS.indexOf(current)
        val next = UNLOCK_OPTIONS[(if (at < 0) 0 else at + 1) % UNLOCK_OPTIONS.size]
        prefs(c).edit().putInt(KEY_UNLOCK_MINUTES, next).apply()
        return true
    }

    /**
     * Verify a typed password and, on success, open a temporary hole in the
     * guard. This is the ONLY place that may call activateUnlock().
     */
    fun verifyAndUnlock(c: Context, inputRaw: String): Result {
        if (!NightGuardManager.isInNightWindow(c)) return Result.NOT_NIGHT
        if (isThrottled(c)) return Result.THROTTLED

        val p = prefs(c)
        val masterHash = p.getString(KEY_MASTER_HASH, "")
        val emergencyHash = p.getString(KEY_EMERGENCY_HASH, "")
        if (masterHash.isNullOrBlank() && emergencyHash.isNullOrBlank()) return Result.NO_KEYS

        val paper = normalizeMaster(inputRaw)
        val digits = inputRaw.filter { !it.isWhitespace() }

        val outcome: Result
        if (!masterHash.isNullOrBlank() && paper.length == MASTER_LENGTH &&
            matches(paper, p.getString(KEY_MASTER_SALT, ""), masterHash)
        ) {
            // Burn it immediately, before anything else can happen.
            p.edit()
                .remove(KEY_MASTER_HASH)
                .remove(KEY_MASTER_SALT)
                .putBoolean(KEY_MASTER_SPENT, true)
                .apply()
            outcome = Result.MASTER
        } else if (!emergencyHash.isNullOrBlank() && isEmergencyShape(digits) &&
            matches(digits, p.getString(KEY_EMERGENCY_SALT, ""), emergencyHash)
        ) {
            p.edit()
                .putInt(KEY_EMERGENCY_COUNT, emergencyUseCount(c) + 1)
                .putLong(KEY_EMERGENCY_LAST, System.currentTimeMillis())
                .apply()
            outcome = Result.EMERGENCY
        } else {
            val fails = p.getInt(KEY_FAIL_COUNT, 0) + 1
            val edit = p.edit().putInt(KEY_FAIL_COUNT, fails)
            if (fails >= MAX_ATTEMPTS) {
                edit.putInt(KEY_FAIL_COUNT, 0)
                    .putLong(
                        KEY_FAIL_UNTIL,
                        System.currentTimeMillis() + LOCKOUT_MINUTES * 60_000L
                    )
            }
            edit.apply()
            return Result.WRONG
        }

        p.edit().putInt(KEY_FAIL_COUNT, 0).remove(KEY_FAIL_UNTIL).apply()
        NightGuardManager.activateUnlock(c, unlockMinutes(c))
        return outcome
    }
}
